// Gamboa: cuantas paginas hay que pedir hoy.
//
// No se pone un numero fijo porque ya se quedo obsoleto una vez. El codigo
// decia "~463 coches = ~20 paginas" y ponia 22; el listado publica hoy 683, o
// sea 29 paginas. El scraper llevaba tiempo viendo poco mas de la mitad del
// concesionario sin que nada lo dijera.
const res = $input.first().json;
const html = String((res && (res.body || res.data)) || (typeof res === 'string' ? res : ''));
const estado = Number((res && res.statusCode) || 200);
if (estado !== 200 || !html) {
  throw new Error('Gamboa devolvio HTTP ' + estado + ' al contar el catalogo — run detenido');
}

const POR_PAGINA = 24;
const m = html.match(/(\d[\d.]{1,6})\s*(?:coches|veh[ií]culos|resultados)/i);
const total = m ? Number(String(m[1]).replace(/\./g, '')) : 0;

// Tres paginas de margen, y no por capricho: el listado NO viene en un orden
// estable -la pagina 2 repite 13 de los 24 de la pagina 1- asi que una sola
// pasada nunca ve el catalogo entero por muchas paginas que se pidan. Las que
// sobran devuelven vacio y el IF las descarta.
//
// Que una pasada no lo vea todo no es grave: lo que se pierda hoy lo recoge la
// de mañana, y quien decide de verdad si un coche sigue publicado es el
// verificador, que va a la ficha de cada uno. El scraper esta para descubrir
// coches nuevos, no para dar de baja.
const paginas = total > 0 ? Math.ceil(total / POR_PAGINA) + 3 : 32;

console.log('[gamboa] el listado publica ' + (total || '?') + ' coches -> ' + paginas + ' paginas');

const out = [];
for (let p = 1; p <= paginas; p++) {
  out.push({ json: {
    url: 'https://www.gamboaocasion.com/coches-ocasion-madrid' + (p > 1 ? '?pagina=' + p : ''),
    pagina: p,
  } });
}
return out;

// Gamboa – transform: HTML de listado (?pagina=N) → tarjetas → UPSERT en moveadvisor_marketplace_vo_offers
const httpOut = $input.item.json;
const html = typeof httpOut === 'string' ? httpOut : String(httpOut.data || httpOut.body || '');

// fullResponse deja ver el codigo de estado y neverError impide que un error
// detenga el run. Sin mirarlo aqui, una pagina de error se parsearia como un
// HTML sin coches y el scraper se quedaria en silencio guardando cero ofertas.
// Se lanza el error a proposito para que salte el Error Handler.
const estado = (httpOut && typeof httpOut === 'object') ? Number(httpOut.statusCode || 0) : 200;
if (estado && estado !== 200) {
  throw new Error('Gamboa devolvio HTTP ' + estado + ' — run detenido');
}
const BASE = 'https://www.gamboaocasion.com';

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return isNaN(v) ? 'NULL' : String(v);
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function normFuel(s) {
  s = String(s || '').toLowerCase();
  if (s.indexOf('eléctric') !== -1 || s.indexOf('electric') !== -1) return 'Eléctrico';
  const ench = s.indexOf('enchufable') !== -1 && s.indexOf('no enchufable') === -1;
  if (s.indexOf('híbrido') !== -1 || s.indexOf('hibrido') !== -1) return ench ? 'Híbrido enchufable' : 'Híbrido';
  if (s.indexOf('diésel') !== -1 || s.indexOf('diesel') !== -1) return 'Diesel';
  if (s.indexOf('gasolina') !== -1) return 'Gasolina';
  if (s.indexOf('glp') !== -1 || s.indexOf('gnc') !== -1 || s.indexOf('gas ') !== -1) return 'Gas';
  return '';
}
function normGear(s) {
  s = String(s || '').toLowerCase();
  if (s.indexOf('autom') !== -1) return 'Automatica';
  if (s.indexOf('manual') !== -1) return 'Manual';
  return '';
}

// localizar cada tarjeta por su <a title="Coche ..." href="...-ID">
const anchorRe = /<a title="Coche ([^"]*?)"\s+href="(\/[a-z0-9-]+-ocasion-madrid\/[a-z0-9-]+-(\d+))"/gi;
const anchors = [];
let m;
while ((m = anchorRe.exec(html)) !== null) anchors.push({ name: m[1].trim(), href: m[2], id: m[3], index: m.index });

const seen = {};
const rows = [];
for (let i = 0; i < anchors.length; i++) {
  const a = anchors[i];
  if (seen[a.id]) continue;
  seen[a.id] = 1;
  const block = html.slice(a.index, anchors[i + 1] ? anchors[i + 1].index : a.index + 2600);

  const ctitle = (block.match(/<h3 class="card-title">([^<]*)<\/h3>/i) || [])[1] || '';
  const brandModel = ctitle.replace(/\s+/g, ' ').trim();
  const sp = brandModel.indexOf(' ');
  const brand = sp === -1 ? brandModel : brandModel.slice(0, sp);
  const model = sp === -1 ? '' : brandModel.slice(sp + 1);
  const version = ((block.match(/<p class="card-text">([^<]*)<\/p>/i) || [])[1] || '').replace(/\s+/g, ' ').trim();
  const title = (a.name || (brandModel + ' ' + version)).replace(/\s+/g, ' ').trim();

  const img = (block.match(/src="(\/img\/coches\/\d+\/[^"]+)"/i) || [])[1] || '';
  const imageUrl = img ? (BASE + img) : '';

  const priceM = block.match(/€\s*(\d{1,3}(?:\.\d{3})+)/);
  const price = priceM ? priceM[1].replace(/\./g, '') : null;

  const text = block.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
  const powerM = text.match(/(\d{2,4})\s*cv/i);
  const power = powerM ? (powerM[1] + ' CV') : null;
  const yearM = text.match(/\b(20\d{2}|19\d{2})\b/);
  const year = yearM ? yearM[1] : null;
  const kmM = text.match(/(\d{1,3}(?:\.\d{3})*)\s*km/i);
  const mileage = kmM ? kmM[1].replace(/\./g, '') : null;
  const fuel = normFuel(text);
  const transmission = normGear(text);

  if (!price) continue; // sin precio no insertamos (obligatorio)

  const id = 'gamboa_' + a.id;
  const row = '(' +
    esc(id) + ', ' + esc(title) + ', ' + esc(brand) + ', ' + esc(model) + ', ' + esc(version) + ', ' +
    price + ', ' + (year || 'NULL') + ', ' + (mileage || 'NULL') + ', ' +
    esc(fuel) + ', ' + esc(power) + ', ' + esc(transmission) + ', ' +
    esc(imageUrl) + ', ' + esc(BASE + a.href) + ', ' +
    "'usado', 'concesionario', 'gamboa', 'Gamboa Ocasión', 'Madrid', 'Madrid', true, true, NOW(), NOW()" +
  ')';
  rows.push(row);
}

if (!rows.length) return [{ json: { sql: null, count: 0 } }];

const cols = 'id, title, brand, model, version, price, year, mileage, fuel, power, transmission, ' +
  'image_url, source_url, vehicle_condition, seller_type, portal, seller, location, provincia, ' +
  'available_for_purchase, is_active, created_at, updated_at';

// Los campos cuyo cambio SI es un cambio del anuncio. Si ninguno se mueve, lo
// unico que ha pasado es que hemos vuelto a pasar por delante.
const CAMPOS_QUE_CAMBIAN = ['title', 'price', 'mileage', 'version', 'fuel',
  'power', 'transmission', 'source_url'];
const HA_CAMBIADO = CAMPOS_QUE_CAMBIAN
  .map(function (f) {
    return 'moveadvisor_marketplace_vo_offers.' + f + ' IS DISTINCT FROM EXCLUDED.' + f;
  })
  // Volver a publicarse tambien es un cambio de estado que merece fecha nueva.
  .concat(['moveadvisor_marketplace_vo_offers.is_active IS DISTINCT FROM TRUE'])
  .join(' OR ');

// updated_at NO se toca si el anuncio no ha cambiado.
//
// Ponerlo a NOW() en cada pasada parecia inofensivo y no lo era. El escaparate
// ordena por portal_score y, como todos los concesionarios valen 80, el
// desempate real es updated_at DESC. Cada pasada del scraper colocaba las 609
// filas de Gamboa por delante de VIAN y de Modrive: el 2026-09-06 las primeras
// 300 filas del listado eran todas de Gamboa, y el filtro de vendedor del ERP
// -que se construye con lo que la tabla llega a cargar- ya solo ofrecia Gamboa.
// VIAN y Modrive no habian desaparecido: estaban detras de 609 coches.
//
// Y habria ido a peor segun montaramos scraper y verificador para cada
// concesionario: el orden de la tienda acabaria dependiendo de nuestro
// calendario de mantenimiento en vez de cuando cambio el anuncio.
//
// last_seen_at y last_checked_at si se mueven siempre: esos SI son "cuando
// pasamos por delante", que es justo lo que significan.
const onConflict = 'ON CONFLICT (id) DO UPDATE SET ' +
  'title = EXCLUDED.title, price = EXCLUDED.price, mileage = EXCLUDED.mileage, ' +
  'year = COALESCE(EXCLUDED.year, moveadvisor_marketplace_vo_offers.year), ' +
  'version = EXCLUDED.version, fuel = EXCLUDED.fuel, power = EXCLUDED.power, ' +
  'transmission = EXCLUDED.transmission, ' +
  "image_url = COALESCE(NULLIF(moveadvisor_marketplace_vo_offers.image_url,''), EXCLUDED.image_url), " +
  'source_url = EXCLUDED.source_url, is_active = TRUE, ' +
  'updated_at = CASE WHEN ' + HA_CAMBIADO +
    ' THEN NOW() ELSE moveadvisor_marketplace_vo_offers.updated_at END, ' +
  'last_seen_at = NOW(), last_checked_at = NOW()';

const sql = 'INSERT INTO moveadvisor_marketplace_vo_offers (' + cols + ') VALUES ' + rows.join(', ') + ' ' + onConflict;
return [{ json: { sql: sql, count: rows.length } }];
